/// <summary>
/// Contract class for generating a dialog fields/parameters used for batch execution to Update Stock availability details for the replenishment sites fetching information from the related parent site.
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessing(classStr(METUpdateStockAvailabilitySourceOfSupplyChangeUIBuilder))
]
internal final class METUpdateStockAvailabilitySourceOfSupplyChangeContract implements SysOperationValidatable
{
    private ItemId itemId;
    //private InventSiteId siteId;
    //private METStockAvailDate stockAvailabilityDate;
    //private EcoResProductLifecycleStateId productLifeCycleStateId;
    //private InventLocationIdReqMain mainWarehouse;

    private InventLocationId warehouseId;
    private ReqPOType plannedOrderType;
    private NoYes metIntercompanySourced;
    private InventLocationId metIntercompanySourcedWarehouseId;

}

Method.Source:
/// <summary>
/// Get/Set Site parameter.
/// </summary>
/// <param name = "_siteId">InventLocationId</param>
/// <returns>InventLocationId as parameters cannot be blank or invalid Site value</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@SYS6437"))
]
public InventLocationId parmInventLocationId(InventLocationId _warehouseId = warehouseId)
{
    warehouseId = _warehouseId;
    return warehouseId;
}

/// <summary>
/// Get/Set Item number parameter.
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns>ItemId always, as parameters cannot be blank or invalid Item number value</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@MET:ItemNumber"))
]
public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

/// <summary>
/// Get/Set planned order type.
/// </summary>
/// <param name = "ReqPOType">Planned order type</param>
/// <returns>Planned order type as parameters cannot be blank or invalid.</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@SYS17749"))
]
public ReqPOType parmPlannedOrderTpye(ReqPOType _plannedOrderType = plannedOrderType)
{
    plannedOrderType = _plannedOrderType;
    return plannedOrderType;
}

/// <summary>
/// Get/Set Metcash intercompany sourced parameter.
/// </summary>
/// <param name = "_metIntercompanySourced">Metcash Intercompany sourced</param>
/// <returns>Metcash intercompany sourced parameters value</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@MET:InterCompanySourced"))
]
public NoYes parmMetIntercompanySourced(NoYes _metIntercompanySourced = metIntercompanySourced)
{
    metIntercompanySourced = _metIntercompanySourced;
    return metIntercompanySourced;
}

/// <summary>
/// Get/Set Metcash intercompany sourced warehouse parameter.
/// </summary>
/// <param name = "_metIntercompanySourced">Metcash Intercompany sourced</param>
/// <returns>Metcash intercompany sourced parameters value</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@MET:IntercompanySourcedWarehouse"))
]
public InventLocationId parmMetIntercompanySourcedWarehouseId(InventLocationId _metIntercompanySourcedWarehouseId = metIntercompanySourcedWarehouseId)
{
    metIntercompanySourcedWarehouseId = _metIntercompanySourcedWarehouseId;
    return metIntercompanySourcedWarehouseId;
}

/// <summary>
/// This implementation of the interface validates the values of the contract parameters.
/// </summary>
/// <returns>Boolean True, upon successful validation checks, otherwise false</returns>
public boolean validate()
{
    boolean ret = true;

    if (!warehouseId)
    {
        ret = checkFailed("@MET:CoverageWarehouseCannotBeBlank");
    }

    if (METVendParameters::find().UpdateFromParentToTransferSites == NoYes::No)
    {
        ret = checkfailed("@MET:UpdateFromParentToTransferSitesParameterNoSet");
    }

    return ret;
}
